import java.util.*;
import java.io.*;

class Solution {
        public List<List<String>> displayTable(List<List<String>> orders) {
            Map<Integer, Map<String, Integer>> counts = new HashMap<>();
            Set<String> foods = new HashSet<>();

            for (List<String> order : orders) {
                int table = Integer.parseInt(order.get(1));
                String food = order.get(2);
                counts.computeIfAbsent(table, k -> new HashMap<>())
                      .merge(food, 1, Integer::sum);
                foods.add(food);
            }

            List<String> foodList = new ArrayList<>(foods);
            Collections.sort(foodList);
            List<Integer> tables = new ArrayList<>(counts.keySet());
            Collections.sort(tables);

            List<List<String>> result = new ArrayList<>();
            List<String> header = new ArrayList<>();
            header.add("Table");
            header.addAll(foodList);
            result.add(header);

            for (int table : tables) {
                List<String> row = new ArrayList<>();
                row.add(String.valueOf(table));
                Map<String, Integer> rowCounts = counts.get(table);
                for (String food : foodList) {
                    row.add(String.valueOf(rowCounts.getOrDefault(food, 0)));
                }
                result.add(row);
            }
            return result;
        }
    }

