using namespace std;

class Solution {
public:
    vector<vector<string>> displayTable(vector<vector<string>>& orders) {
        map<int, map<string, int>> counts;
        set<string> foods;

        for (const auto& order : orders) {
            int table = stoi(order[1]);
            const string& food = order[2];
            counts[table][food]++;
            foods.insert(food);
        }

        vector<string> foodList(foods.begin(), foods.end());
        vector<vector<string>> result;
        vector<string> header = {"Table"};
        header.insert(header.end(), foodList.begin(), foodList.end());
        result.push_back(header);

        for (const auto& [table, rowCounts] : counts) {
            vector<string> row = {to_string(table)};
            for (const string& food : foodList) {
                auto it = rowCounts.find(food);
                row.push_back(it == rowCounts.end() ? "0" : to_string(it->second));
            }
            result.push_back(row);
        }
        return result;
    }
};

vector<string> quotedStrings(const string& s) {
    vector<string> values;
    string cur;
    bool in = false, escape = false;
    for (char c : s) {
        if (!in) {
            if (c == '"') {
                in = true;
                cur.clear();
            }
        } else if (escape) {
            cur.push_back(c);
            escape = false;
        } else if (c == '\\') {
            escape = true;
        } else if (c == '"') {
            values.push_back(cur);
            in = false;
        } else {
            cur.push_back(c);
        }
    }
