    static List<String> quotedStrings(String s) {
        List<String> values = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        boolean in = false, escape = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!in) {
                if (c == '"') {
                    in = true;
                    cur.setLength(0);
                }
            } else if (escape) {
                cur.append(c);
                escape = false;
            } else if (c == '\\') {
                escape = true;
            } else if (c == '"') {
                values.add(cur.toString());
                in = false;
            } else {
                cur.append(c);
            }
        }
        return values;
    }

    static String jsonEscape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    static String serialize(List<List<String>> result) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('[');
            for (int j = 0; j < result.get(i).size(); j++) {
                if (j > 0) sb.append(',');
                sb.append('"').append(jsonEscape(result.get(i).get(j))).append('"');
            }
            sb.append(']');
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        String input = new BufferedReader(new InputStreamReader(System.in)).readLine();
        List<String> values = quotedStrings(input);
        List<List<String>> orders = new ArrayList<>();
        for (int i = 0; i + 2 < values.size(); i += 3) {
